examples.template:
Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4)) {
    MonarchDescriptionList(
        items = listOf(
            MonarchDescriptionItem({{regime.term}}, {{regime.value}}),
            MonarchDescriptionItem({{status.term}}, {{status.value}}),
            MonarchDescriptionItem({{categories.0.label}}, null, content = { MonarchBadge(text = {{categories.0.badge}}, tone = {{categories.0.tone|tone}}) }),
            MonarchDescriptionItem({{categories.1.label}}, null, content = { MonarchBadge(text = {{categories.1.badge}}, tone = {{categories.1.tone|tone}}) }),
            MonarchDescriptionItem({{categories.2.label}}, null, content = { MonarchBadge(text = {{categories.2.badge}}, tone = {{categories.2.tone|tone}}) }),
            MonarchDescriptionItem({{categories.3.label}}, null, content = { MonarchBadge(text = {{categories.3.badge}}, tone = {{categories.3.tone|tone}}) }),
        ),
        layout = MonarchDescriptionListLayout.Inline,
    )
    FlowRow(horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
        MonarchButton(text = {{actions.rejectAll}}, onClick = {}, variant = MonarchButtonVariant.Secondary, size = MonarchButtonSize.Sm)
        MonarchButton(text = {{actions.acceptAll}}, onClick = {}, variant = MonarchButtonVariant.Secondary, size = MonarchButtonSize.Sm)
        MonarchButton(text = {{actions.withdraw}}, onClick = {}, variant = MonarchButtonVariant.Ghost, size = MonarchButtonSize.Sm)
    }
    MonarchText(text = {{fallback}}, color = MonarchTheme.colors.textMuted)
}

